{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Validate required fields
    if nodes is None or core_distance is None or distances is None:
        raise ValueError("Missing required fields: nodes, core_distance, or distances")
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core_distance for node {node}")

    n = len(nodes)

    # Compute mutual reachability for each edge and canonicalize endpoints
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        if u not in core_distance:
            raise ValueError(f"Missing core_distance for node {u}")
        if v not in core_distance:
            raise ValueError(f"Missing core_distance for node {v}")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize: lexicographic order so u < v
        if u > v:
            u, v = v, u
        mr_edges.append((mr, u, v))

    # Sort deterministically: by mutual reachability weight, then by endpoint IDs
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find for Kruskal's MST
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        # Union by rank
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot span all nodes")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
